import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import type { StyleTag } from '@/lib/supabase/types'

// ── List all style tags for a studio ─────────────────────────────────────────

export async function listStyleTags(studioId: string): Promise<StyleTag[]> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('style_tags')
    .select('*')
    .eq('studio_id', studioId)
    .order('sort_order', { ascending: true })
    .order('name', { ascending: true })

  if (error) {
    logger.error({ error, studioId }, 'listStyleTags failed')
    throw new Error('Failed to load style tags')
  }

  return data ?? []
}

// ── Create a style tag ────────────────────────────────────────────────────────

export interface StyleTagCreateInput {
  name: string
  color?: string | null
  icon?: string | null
  description?: string | null
  sortOrder?: number
}

export async function createStyleTag(
  studioId: string,
  input: StyleTagCreateInput
): Promise<StyleTag> {
  const supabase = await createClient()

  const slug = input.name
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')

  const { data, error } = await supabase
    .from('style_tags')
    .insert({
      studio_id: studioId,
      slug,
      name: input.name,
      color: input.color ?? null,
      icon: input.icon ?? null,
      description: input.description ?? null,
      sort_order: input.sortOrder ?? 0,
    })
    .select()
    .single()

  if (error) {
    logger.error({ error, studioId }, 'createStyleTag failed')
    if (error.code === '23505') {
      throw new Error('A style tag with this name already exists.')
    }
    throw new Error('Failed to create style tag')
  }

  return data
}

// ── Update a style tag ────────────────────────────────────────────────────────

export interface StyleTagUpdateInput {
  name?: string
  color?: string | null
  icon?: string | null
  description?: string | null
  sortOrder?: number
}

export async function updateStyleTag(
  studioId: string,
  tagId: string,
  input: StyleTagUpdateInput
): Promise<StyleTag> {
  const supabase = await createClient()

  const updatePayload: Record<string, unknown> = {}
  if (input.name !== undefined) {
    updatePayload.name = input.name
    updatePayload.slug = input.name
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
  }
  if (input.color !== undefined) updatePayload.color = input.color
  if (input.icon !== undefined) updatePayload.icon = input.icon
  if (input.description !== undefined) updatePayload.description = input.description
  if (input.sortOrder !== undefined) updatePayload.sort_order = input.sortOrder

  const { data, error } = await supabase
    .from('style_tags')
    .update(updatePayload)
    .eq('id', tagId)
    .eq('studio_id', studioId)
    .select()
    .single()

