import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import type { ArtistPortfolioItem } from '@/lib/supabase/types'

const PORTFOLIO_BUCKET = 'artist-portfolio'
const MAX_SIZE_BYTES = 10 * 1024 * 1024 // 10 MB
const ALLOWED_MIME_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif']

// ── List portfolio items for an artist ───────────────────────────────────────

export async function fetchArtistPortfolio(
  studioId: string,
  artistId: string
): Promise<ArtistPortfolioItem[]> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('artist_portfolio_items')
    .select('*')
    .eq('studio_id', studioId)
    .eq('artist_id', artistId)
    .order('display_order', { ascending: true })
    .order('created_at', { ascending: false })

  if (error) {
    logger.error({ error, studioId, artistId }, 'fetchArtistPortfolio failed')
    throw new Error('Failed to load portfolio')
  }

  return data ?? []
}

// ── List featured portfolio items for an entire studio ───────────────────────

export async function fetchStudioPortfolio(
  studioId: string,
  options: { artistId?: string; styleTagId?: string; featuredOnly?: boolean } = {}
): Promise<(ArtistPortfolioItem & { artist: { id: string; display_name: string; slug: string | null; avatar_url: string | null } })[]> {
  const supabase = await createClient()

  let query = supabase
    .from('artist_portfolio_items')
    .select(`
      *,
      artist:artists(id, display_name, avatar_url, slug)
    `)
    .eq('studio_id', studioId)
    .order('display_order', { ascending: true })

  if (options.featuredOnly) {
    query = query.eq('is_featured', true)
  }
  if (options.artistId) {
    query = query.eq('artist_id', options.artistId)
  }
  if (options.styleTagId) {
    query = query.contains('style_tag_ids', [options.styleTagId])
  }

  const { data, error } = await query

  if (error) {
    logger.error({ error, studioId }, 'fetchStudioPortfolio failed')
    throw new Error('Failed to load studio portfolio')
  }

  return (data ?? []) as (ArtistPortfolioItem & { artist: { id: string; display_name: string; slug: string | null; avatar_url: string | null } })[]
}

// ── Public: fetch portfolio items (anon read on public bucket) ───────────────

export async function fetchPublicArtistPortfolio(
  artistId: string
): Promise<ArtistPortfolioItem[]> {
  // Use server client — RLS allows public read on artist_portfolio_items
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('artist_portfolio_items')
    .select('*')
    .eq('artist_id', artistId)
    .order('display_order', { ascending: true })

  if (error) {
    logger.error({ error, artistId }, 'fetchPublicArtistPortfolio failed')
    return []
  }

  return data ?? []
}

