// ── Delete a portfolio item (also removes from storage) ──────────────────────

export async function deletePortfolioItem(
  studioId: string,
  itemId: string
): Promise<void> {
  const supabase = await createClient()

  // Fetch first to get storage_path for cleanup
  const { data: item } = await supabase
    .from('artist_portfolio_items')
    .select('storage_path')
    .eq('id', itemId)
    .eq('studio_id', studioId)
    .maybeSingle()

  const { error } = await supabase
    .from('artist_portfolio_items')
    .delete()
    .eq('id', itemId)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ error, studioId, itemId }, 'deletePortfolioItem failed')
    throw new Error('Failed to delete portfolio item')
  }

  // Best-effort storage cleanup
  if (item?.storage_path) {
    await supabase.storage
      .from(PORTFOLIO_BUCKET)
      .remove([item.storage_path])
      .catch((err: unknown) => logger.error({ err, path: item.storage_path }, 'portfolio storage cleanup failed'))
  }
}

// ── Reorder portfolio items ────────────────────────────────────────────────────

export async function reorderPortfolioItems(
  studioId: string,
  orderedIds: string[]
): Promise<void> {
  const supabase = await createClient()

  await Promise.all(
    orderedIds.map((id, index) =>
      supabase
        .from('artist_portfolio_items')
        .update({ display_order: index })
        .eq('id', id)
        .eq('studio_id', studioId)
    )
  )
}

// ── Promote a booking photo to portfolio ─────────────────────────────────────

export interface PromotePhotoInput {
  bookingPhotoId: string
  artistId: string
  caption?: string | null
  styleTagIds?: string[]
  createdBy?: string | null
}

export async function promoteFromBookingPhoto(
  studioId: string,
  input: PromotePhotoInput
): Promise<ArtistPortfolioItem> {
  const supabase = await createClient()

  // Fetch the booking photo record
  const { data: photo, error: photoError } = await supabase
    .from('booking_photos')
    .select('storage_path, kind')
    .eq('id', input.bookingPhotoId)
    .eq('studio_id', studioId)
    .maybeSingle()

  if (photoError || !photo) {
    throw new Error('Booking photo not found')
  }

  // Copy the file to the artist-portfolio bucket
  const filename = photo.storage_path.split('/').pop() ?? `${Date.now()}.jpg`
  const destPath = `${studioId}/${input.artistId}/${filename}`

  // Download then re-upload
  const { data: fileData, error: dlError } = await supabase.storage
    .from('booking-photos')
    .download(photo.storage_path)

  if (dlError || !fileData) {
    logger.error({ dlError, path: photo.storage_path }, 'promoteFromBookingPhoto: download failed')
    throw new Error('Failed to copy photo')
  }

  const { error: uploadError } = await supabase.storage
    .from(PORTFOLIO_BUCKET)
    .upload(destPath, fileData, { upsert: true, contentType: 'image/jpeg' })

  if (uploadError) {
    logger.error({ uploadError, destPath }, 'promoteFromBookingPhoto: upload failed')
    throw new Error('Failed to upload photo to portfolio')
  }

  return createPortfolioItem(studioId, {
    artistId: input.artistId,
    storagePath: destPath,
    caption: input.caption ?? null,
    styleTagIds: input.styleTagIds ?? [],
    linkedBookingPhotoId: input.bookingPhotoId,
    createdBy: input.createdBy ?? null,
  })
}

// ── Upload a file and create a portfolio item ─────────────────────────────────

export async function uploadAndCreatePortfolioItem(
  studioId: string,
  artistId: string,
  file: File,
  options: { caption?: string | null; styleTagIds?: string[]; isFeatured?: boolean; createdBy?: string | null }
): Promise<ArtistPortfolioItem> {
  if (!ALLOWED_MIME_TYPES.includes(file.type)) {
    throw new Error('Only JPEG, PNG, WebP, and GIF files are allowed')
  }
  if (file.size > MAX_SIZE_BYTES) {
    throw new Error('File must be under 10 MB')
  }

  const supabase = await createClient()

  const ext = file.name.split('.').pop() ?? 'jpg'
  const filename = `${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`
  const storagePath = `${studioId}/${artistId}/${filename}`

  const { error: uploadError } = await supabase.storage
    .from(PORTFOLIO_BUCKET)
    .upload(storagePath, file, { contentType: file.type, upsert: false })

  if (uploadError) {
    logger.error({ uploadError, studioId, artistId }, 'uploadAndCreatePortfolioItem: upload failed')
    throw new Error('Failed to upload image')
  }

  return createPortfolioItem(studioId, {
    artistId,
    storagePath,
    caption: options.caption ?? null,
    styleTagIds: options.styleTagIds ?? [],
    isFeatured: options.isFeatured ?? false,
    createdBy: options.createdBy ?? null,
  })
}

// ── Get public URL for a portfolio storage path ───────────────────────────────

export function getPortfolioPublicUrl(storagePath: string): string {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''
  return `${supabaseUrl}/storage/v1/object/public/${PORTFOLIO_BUCKET}/${storagePath}`
}

