// POST /api/portfolio — multipart/form-data upload
const createSchema = z.object({
  artistId: z.string().uuid(),
  caption: z.string().max(500).optional().nullable(),
  styleTagIds: z.array(z.string().uuid()).optional(),
  isFeatured: z.boolean().optional(),
})

export async function POST(req: Request) {
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin', 'artist'].includes(auth.role)) {
    return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 })
  }

  let formData: FormData
  try {
    formData = await req.formData()
  } catch {
    return NextResponse.json({ error: 'Expected multipart/form-data' }, { status: 400 })
  }

  const file = formData.get('file')
  if (!(file instanceof File)) {
    return NextResponse.json({ error: 'file is required' }, { status: 400 })
  }

  const styleTagIdsRaw = formData.get('styleTagIds')
  let styleTagIds: string[] = []
  if (typeof styleTagIdsRaw === 'string' && styleTagIdsRaw) {
    try {
      const parsed = JSON.parse(styleTagIdsRaw) as unknown
      if (Array.isArray(parsed)) styleTagIds = parsed as string[]
    } catch {
      // ignore malformed
    }
  }

  const raw = {
    artistId: formData.get('artistId'),
    caption: formData.get('caption') || null,
    styleTagIds,
    isFeatured: formData.get('isFeatured') === 'true',
  }

  const parsed = createSchema.safeParse(raw)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.errors[0]?.message ?? 'Validation failed' }, { status: 400 })
  }

  try {
    const item = await uploadAndCreatePortfolioItem(
      auth.studioId,
      parsed.data.artistId,
      file,
      {
        caption: parsed.data.caption ?? null,
        styleTagIds: parsed.data.styleTagIds ?? [],
        isFeatured: parsed.data.isFeatured ?? false,
        createdBy: auth.user.id,
      }
    )
    return NextResponse.json({ data: item }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'POST /api/portfolio failed')
    const message = err instanceof Error ? err.message : 'Failed to upload'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

