  bookingPhotoId: z.string().uuid(),
  artistId: z.string().uuid(),
  caption: z.string().max(500).optional().nullable(),
  styleTagIds: z.array(z.string().uuid()).optional(),
})

export async function POST(req: Request) {
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin', 'artist'].includes(auth.role)) {
    return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = promoteSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.errors[0]?.message ?? 'Validation failed' }, { status: 400 })
  }

  try {
    const item = await promoteFromBookingPhoto(auth.studioId, {
      bookingPhotoId: parsed.data.bookingPhotoId,
      artistId: parsed.data.artistId,
      caption: parsed.data.caption ?? null,
      styleTagIds: parsed.data.styleTagIds ?? [],
      createdBy: auth.user.id,
    })
    return NextResponse.json({ data: item }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'POST /api/portfolio/promote failed')
    const message = err instanceof Error ? err.message : 'Failed to promote photo'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

