import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { addDesign, reorderDesigns } from '@/lib/flash-events/mutations'
import { flashDesignCreateSchema } from '@/lib/flash-events/schemas'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

// POST — add a design OR reorder (action discriminated by ?action=reorder)
export async function POST(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin', 'artist', 'receptionist'].includes(auth.role)) {
    return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 })
  }

  const url = new URL(req.url)
  const action = url.searchParams.get('action')

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  if (action === 'reorder') {
    const parsed = z.object({ orderedIds: z.array(z.string().uuid()).min(1) }).safeParse(body)
    if (!parsed.success) return NextResponse.json({ error: 'orderedIds required' }, { status: 400 })
    await reorderDesigns(auth.studioId, id, parsed.data.orderedIds)
    return NextResponse.json({ success: true })
  }

  // Add design — merge style_tag_ids into schema
  const extendedSchema = flashDesignCreateSchema.extend({
    styleTagIds: z.array(z.string().uuid()).optional(),
  })

  const parsed = extendedSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.errors[0]?.message ?? 'Validation failed' }, { status: 400 })
  }

  try {
    const design = await addDesign(auth.studioId, id, {
      title: parsed.data.title,
      imageUrl: parsed.data.imageUrl,
      sizeDescription: parsed.data.sizeDescription,
      placementOptions: parsed.data.placementOptions,
      priceCents: parsed.data.priceCents,
      displayOrder: parsed.data.displayOrder,
    })

    // Update style_tag_ids if provided
    if (parsed.data.styleTagIds?.length) {
      const { createClient } = await import('@/lib/supabase/server')
      const supabase = await createClient()
      await supabase
        .from('flash_event_designs')
        .update({ style_tag_ids: parsed.data.styleTagIds })
        .eq('id', design.id)
    }

    return NextResponse.json({ data: design }, { status: 201 })
  } catch (err) {
    logger.error({ err, id }, 'POST /api/flash-events/[id]/designs failed')
    const message = err instanceof Error ? err.message : 'Failed to add design'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

