import { NextResponse } from 'next/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { blockSlot, unblockSlot } from '@/lib/flash-events/mutations'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

// POST with ?action=block or ?action=unblock
export async function POST(
  req: Request,
  { params }: { params: Promise<{ id: string; slotId: string }> }
) {
  const { id, slotId } = await params
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) {
    return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 })
  }

  const url = new URL(req.url)
  const action = url.searchParams.get('action') ?? 'block'

  try {
    if (action === 'unblock') {
      const slot = await unblockSlot(auth.studioId, id, slotId)
      return NextResponse.json({ data: slot })
    } else {
      const slot = await blockSlot(auth.studioId, id, slotId)
      return NextResponse.json({ data: slot })
