import type { StyleTag } from '@/lib/supabase/types'

const PRESET_COLORS = [
  '#6366f1', '#8b5cf6', '#ec4899', '#f43f5e',
  '#f97316', '#eab308', '#22c55e', '#06b6d4',
  '#3b82f6', '#64748b',
]

// ── Editor Dialog ────────────────────────────────────────────────────────────

interface EditorDialogProps {
  tag: StyleTag | null
  open: boolean
  onOpenChange: (open: boolean) => void
  onSaved: () => void
}

function StyleTagEditor({ tag, open, onOpenChange, onSaved }: EditorDialogProps) {
  const isEdit = !!tag
  const [name, setName] = useState(tag?.name ?? '')
  const [color, setColor] = useState<string>(tag?.color ?? PRESET_COLORS[0] ?? '#6366f1')
  const [description, setDescription] = useState(tag?.description ?? '')
  const [saving, setSaving] = useState(false)

  // Reset form when tag prop changes
  useEffect(() => {
    setName(tag?.name ?? '')
    setColor(tag?.color ?? PRESET_COLORS[0] ?? '#6366f1')
    setDescription(tag?.description ?? '')
  }, [tag])

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    if (!name.trim()) return

    setSaving(true)
    try {
      const url = isEdit ? `/api/style-tags/${tag.id}` : '/api/style-tags'
      const method = isEdit ? 'PATCH' : 'POST'

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: name.trim(), color, description: description || null }),
      })

      if (!res.ok) {
        const j = await res.json() as { error?: string }
        throw new Error(j.error ?? 'Failed to save')
      }

      toast.success(isEdit ? 'Style tag updated' : 'Style tag created')
      onSaved()
      onOpenChange(false)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to save style tag')
    } finally {
      setSaving(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-sm">
        <DialogHeader>
          <DialogTitle>{isEdit ? 'Edit style tag' : 'New style tag'}</DialogTitle>
        </DialogHeader>

        <form onSubmit={(e) => void handleSubmit(e)} className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="st-name">Name *</Label>
            <Input
              id="st-name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g. Fine Line"
              maxLength={80}
              required
            />
          </div>

          <div className="space-y-1.5">
            <Label>Color</Label>
            <div className="flex flex-wrap gap-1.5">
              {PRESET_COLORS.map((c) => (
                <button
                  key={c}
                  type="button"
                  className={cn(
                    'h-6 w-6 rounded-full border-2 transition-all',
                    color === c ? 'border-foreground scale-110' : 'border-transparent hover:scale-105'
                  )}
                  style={{ backgroundColor: c }}
                  onClick={() => setColor(c)}
                  aria-label={`Select color ${c}`}
                />
              ))}
              <input
                type="color"
                value={color}
                onChange={(e) => setColor(e.target.value)}
                className="h-6 w-6 rounded-full border-2 border-transparent cursor-pointer"
                title="Custom color"
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="st-desc">Description</Label>
            <Input
              id="st-desc"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Optional description"
              maxLength={300}
            />
          </div>

          {/* Preview */}
          <div className="flex items-center gap-2 p-2.5 rounded-lg bg-muted/40">
            <span className="text-xs text-muted-foreground">Preview:</span>
            <span className="inline-flex items-center gap-1 rounded-full border border-border/60 px-2.5 py-0.5 text-xs font-medium">
              {color && (
                <span
                  className="h-1.5 w-1.5 rounded-full shrink-0"
                  style={{ backgroundColor: color }}
                />
              )}
              {name || 'Tag name'}
            </span>
          </div>

          <DialogFooter>
            <Button variant="outline" type="button" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={saving || !name.trim()}>
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {isEdit ? 'Save changes' : 'Create tag'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

// ── Main Manager ─────────────────────────────────────────────────────────────

export function StyleTagsManager() {
  const [tags, setTags] = useState<StyleTag[]>([])
  const [loading, setLoading] = useState(true)
  const [editorOpen, setEditorOpen] = useState(false)
  const [editingTag, setEditingTag] = useState<StyleTag | null>(null)

  const fetchTags = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/style-tags')
      if (!res.ok) throw new Error('Failed to load')
      const j = await res.json() as { data: StyleTag[] }
      setTags(j.data ?? [])
    } catch {
      toast.error('Failed to load style tags')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => { void fetchTags() }, [fetchTags])

  const openCreate = () => {
    setEditingTag(null)
    setEditorOpen(true)
  }

  const openEdit = (tag: StyleTag) => {
    setEditingTag(tag)
    setEditorOpen(true)
  }

  const handleDelete = async (tagId: string) => {
    try {
      const res = await fetch(`/api/style-tags/${tagId}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Delete failed')
      toast.success('Style tag deleted')
      setTags((prev) => prev.filter((t) => t.id !== tagId))
    } catch {
      toast.error('Failed to delete style tag')
    }
  }

  return (
    <>
      <Card className="shadow-soft">
        <CardHeader className="pb-4">
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-base font-semibold">Style tags</CardTitle>
              <CardDescription className="text-sm mt-0.5">
                Categorize flash designs and portfolio items. Clients can filter by style on the booking page.
              </CardDescription>
            </div>
            <Button size="sm" onClick={openCreate}>
              <Plus className="h-3.5 w-3.5 mr-1.5" />
              New tag
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="space-y-2">
              {Array.from({ length: 4 }).map((_, i) => (
                <Skeleton key={i} className="h-10 w-full rounded-lg" />
              ))}
            </div>
          ) : tags.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-10 text-center">
              <div className="h-10 w-10 rounded-xl bg-muted flex items-center justify-center mb-3">
                <Tag className="h-5 w-5 text-muted-foreground" />
              </div>
              <p className="text-sm font-medium">No style tags yet</p>
              <p className="text-xs text-muted-foreground mt-1 mb-4">
                10 default tags are seeded automatically. Create custom tags for your studio&apos;s specialties.
              </p>
              <Button size="sm" variant="outline" onClick={openCreate}>
                <Plus className="h-3.5 w-3.5 mr-1.5" />
                Create first tag
              </Button>
            </div>
          ) : (
            <div className="space-y-1">
              {tags.map((tag) => (
                <div
                  key={tag.id}
                  className="flex items-center gap-3 rounded-lg border border-border/40 bg-card px-3 py-2.5 group"
                >
                  <span
                    className="h-3 w-3 rounded-full shrink-0"
                    style={{ backgroundColor: tag.color ?? '#94a3b8' }}
                  />
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium">{tag.name}</p>
                    {tag.description && (
                      <p className="text-xs text-muted-foreground truncate">{tag.description}</p>
                    )}
                  </div>
                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-7 w-7"
                      onClick={() => openEdit(tag)}
                      aria-label={`Edit ${tag.name}`}
                    >
                      <Pencil className="h-3.5 w-3.5" />
                    </Button>
                    <AlertDialog>
                      <AlertDialogTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7 text-destructive hover:text-destructive"
                          aria-label={`Delete ${tag.name}`}
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                        </Button>
                      </AlertDialogTrigger>
                      <AlertDialogContent>
                        <AlertDialogHeader>
                          <AlertDialogTitle>Delete &ldquo;{tag.name}&rdquo;?</AlertDialogTitle>
                          <AlertDialogDescription>
                            Existing flash designs and portfolio items will lose this tag. This cannot be undone.
                          </AlertDialogDescription>
                        </AlertDialogHeader>
                        <AlertDialogFooter>
                          <AlertDialogCancel>Cancel</AlertDialogCancel>
                          <AlertDialogAction
                            onClick={() => void handleDelete(tag.id)}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                          >
                            Delete
                          </AlertDialogAction>
                        </AlertDialogFooter>
                      </AlertDialogContent>
                    </AlertDialog>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      <StyleTagEditor
        tag={editingTag}
        open={editorOpen}
        onOpenChange={setEditorOpen}
        onSaved={() => void fetchTags()}
      />
    </>
  )
}

