const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''

function getPublicUrl(storagePath: string) {
  return `${SUPABASE_URL}/storage/v1/object/public/artist-portfolio/${storagePath}`
}

// ── Sortable Item Card ────────────────────────────────────────────────────────

interface SortableItemProps {
  item: ArtistPortfolioItem
  styleTags: StyleTag[]
  canEdit: boolean
  onToggleFeatured: (id: string, current: boolean) => void
  onDelete: (id: string) => void
  onEdit: (item: ArtistPortfolioItem) => void
}

function SortablePortfolioItem({ item, styleTags, canEdit, onToggleFeatured, onDelete, onEdit }: SortableItemProps) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: item.id })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  }

  const imgUrl = getPublicUrl(item.storage_path)

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={cn(
        'relative group rounded-xl overflow-hidden border border-border/50 bg-card',
        isDragging && 'opacity-50 z-50 shadow-card'
      )}
    >
      {/* Drag handle */}
      {canEdit && (
        <div
          {...attributes}
          {...listeners}
          className="absolute top-2 left-2 z-10 opacity-0 group-hover:opacity-100 transition-opacity cursor-grab active:cursor-grabbing"
          aria-label="Drag to reorder"
        >
          <div className="bg-background/80 backdrop-blur-sm rounded p-0.5">
            <GripVertical className="h-4 w-4 text-muted-foreground" />
          </div>
        </div>
      )}

      {/* Featured badge */}
      {item.is_featured && (
        <div className="absolute top-2 right-2 z-10">
          <div className="bg-warning/90 text-warning-foreground rounded-full p-1">
            <Star className="h-3 w-3 fill-current" />
          </div>
        </div>
      )}

      {/* Image */}
      <div className="aspect-square bg-muted overflow-hidden">
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={imgUrl}
          alt={item.caption ?? 'Portfolio photo'}
          className="h-full w-full object-cover"
          loading="lazy"
        />
      </div>

      {/* Info */}
      <div className="p-2 space-y-1">
        {item.caption && (
          <p className="text-xs font-medium line-clamp-1">{item.caption}</p>
        )}
        {item.style_tag_ids.length > 0 && (
          <StyleTagChips tagIds={item.style_tag_ids} tags={styleTags} maxVisible={3} />
        )}
      </div>

      {/* Actions overlay */}
      {canEdit && (
        <div className="absolute inset-0 flex items-center justify-center gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity bg-background/60 backdrop-blur-[2px]">
          <Button
            type="button"
            size="icon"
            variant="secondary"
            className="h-8 w-8"
            onClick={() => onEdit(item)}
            aria-label="Edit portfolio item"
          >
            <Plus className="h-4 w-4 rotate-45" />
          </Button>
          <Button
            type="button"
            size="icon"
            variant={item.is_featured ? 'default' : 'secondary'}
            className="h-8 w-8"
            onClick={() => onToggleFeatured(item.id, item.is_featured)}
            aria-label={item.is_featured ? 'Unfeature' : 'Feature this item'}
            title={item.is_featured ? 'Remove from featured' : 'Add to featured'}
          >
            <Star className={cn('h-4 w-4', item.is_featured && 'fill-current')} />
          </Button>
          <AlertDialog>
            <AlertDialogTrigger asChild>
              <Button
                type="button"
                size="icon"
                variant="destructive"
                className="h-8 w-8"
                aria-label="Delete portfolio item"
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </AlertDialogTrigger>
            <AlertDialogContent>
              <AlertDialogHeader>
                <AlertDialogTitle>Delete this portfolio item?</AlertDialogTitle>
                <AlertDialogDescription>
                  The photo will be permanently removed from the portfolio and storage. This cannot be undone.
                </AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter>
                <AlertDialogCancel>Cancel</AlertDialogCancel>
                <AlertDialogAction
                  onClick={() => onDelete(item.id)}
                  className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                >
                  Delete
                </AlertDialogAction>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>
        </div>
      )}
    </div>
  )
}

// ── Upload/Add Dialog ─────────────────────────────────────────────────────────

interface AddDialogProps {
  artistId: string
  styleTags: StyleTag[]
  open: boolean
  onOpenChange: (open: boolean) => void
  onAdded: () => void
}

function AddPortfolioItemDialog({ artistId, styleTags, open, onOpenChange, onAdded }: AddDialogProps) {
  const [uploading, setUploading] = useState(false)
  const [preview, setPreview] = useState<string | null>(null)
  const [file, setFile] = useState<File | null>(null)
  const [caption, setCaption] = useState('')
  const [selectedTagIds, setSelectedTagIds] = useState<string[]>([])
  const [isFeatured, setIsFeatured] = useState(false)
  const fileRef = useRef<HTMLInputElement>(null)

  function handleFile(f: File) {
    setFile(f)
    const url = URL.createObjectURL(f)
    setPreview(url)
  }

  async function handleUpload(e: React.FormEvent) {
    e.preventDefault()
    if (!file) return

    setUploading(true)
    try {
      const fd = new FormData()
      fd.append('file', file)
      fd.append('artistId', artistId)
      if (caption) fd.append('caption', caption)
      fd.append('styleTagIds', JSON.stringify(selectedTagIds))
      fd.append('isFeatured', String(isFeatured))

      const res = await fetch('/api/portfolio', { method: 'POST', body: fd })
      if (!res.ok) {
        const j = await res.json() as { error?: string }
        throw new Error(j.error ?? 'Upload failed')
      }
      toast.success('Portfolio item added')
      onAdded()
      onOpenChange(false)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Upload failed')
    } finally {
      setUploading(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-sm">
        <DialogHeader>
          <DialogTitle>Add portfolio item</DialogTitle>
        </DialogHeader>

        <form onSubmit={(e) => void handleUpload(e)} className="space-y-4 py-2">
          {/* File drop zone */}
          <div
            className={cn(
              'relative flex flex-col items-center justify-center rounded-xl border-2 border-dashed transition-colors cursor-pointer',
              preview ? 'border-primary/30 p-0 overflow-hidden' : 'border-border/60 hover:border-primary/40 p-6'
            )}
            onClick={() => fileRef.current?.click()}
            onKeyDown={(e) => { if (e.key === 'Enter') fileRef.current?.click() }}
            role="button"
            tabIndex={0}
            aria-label="Upload image"
          >
            {preview ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={preview} alt="Preview" className="w-full aspect-square object-cover" />
            ) : (
              <div className="flex flex-col items-center gap-2 text-center">
                <Upload className="h-8 w-8 text-muted-foreground" />
                <div>
                  <p className="text-sm font-medium">Click to upload</p>
                  <p className="text-xs text-muted-foreground">JPEG, PNG, WebP — max 10 MB</p>
                </div>
              </div>
            )}
            <input
              ref={fileRef}
              type="file"
              accept="image/jpeg,image/png,image/webp,image/gif"
              className="sr-only"
              onChange={(e) => { const f = e.target.files?.[0]; if (f) handleFile(f) }}
            />
          </div>

          {file && (
            <>
              <div className="space-y-1.5">
                <Label htmlFor="pi-caption">Caption</Label>
                <Input
                  id="pi-caption"
                  value={caption}
                  onChange={(e) => setCaption(e.target.value)}
                  placeholder="Describe this piece..."
                  maxLength={500}
                />
              </div>

              <div className="space-y-1.5">
                <Label>Style tags</Label>
                <StyleTagPicker
                  selectedIds={selectedTagIds}
                  onChange={setSelectedTagIds}
                  tags={styleTags}
                />
              </div>

              <div className="flex items-center gap-2">
                <input
                  id="pi-featured"
                  type="checkbox"
                  checked={isFeatured}
                  onChange={(e) => setIsFeatured(e.target.checked)}
                  className="h-4 w-4 rounded border-border"
                />
                <Label htmlFor="pi-featured" className="text-sm font-normal cursor-pointer">
                  Feature on studio portfolio page
                </Label>
              </div>
            </>
          )}

          <DialogFooter>
            <Button variant="outline" type="button" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={!file || uploading}>
              {uploading && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Upload
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

// ── Edit Dialog ───────────────────────────────────────────────────────────────

interface EditDialogProps {
  item: ArtistPortfolioItem | null
  styleTags: StyleTag[]
  open: boolean
  onOpenChange: (open: boolean) => void
  onSaved: () => void
}

function EditPortfolioItemDialog({ item, styleTags, open, onOpenChange, onSaved }: EditDialogProps) {
  const [saving, setSaving] = useState(false)
  const [caption, setCaption] = useState(item?.caption ?? '')
  const [selectedTagIds, setSelectedTagIds] = useState<string[]>(item?.style_tag_ids ?? [])
  const [isFeatured, setIsFeatured] = useState(item?.is_featured ?? false)

  useEffect(() => {
    setCaption(item?.caption ?? '')
    setSelectedTagIds(item?.style_tag_ids ?? [])
    setIsFeatured(item?.is_featured ?? false)
  }, [item])

  async function handleSave(e: React.FormEvent) {
    e.preventDefault()
    if (!item) return
    setSaving(true)
    try {
      const res = await fetch(`/api/portfolio/${item.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          caption: caption || null,
          styleTagIds: selectedTagIds,
          isFeatured,
        }),
      })
      if (!res.ok) throw new Error('Save failed')
      toast.success('Portfolio item updated')
      onSaved()
      onOpenChange(false)
    } catch {
      toast.error('Failed to save changes')
    } finally {
      setSaving(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-sm">
        <DialogHeader>
          <DialogTitle>Edit portfolio item</DialogTitle>
        </DialogHeader>
        <form onSubmit={(e) => void handleSave(e)} className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="edit-caption">Caption</Label>
            <Input
              id="edit-caption"
              value={caption}
              onChange={(e) => setCaption(e.target.value)}
              placeholder="Describe this piece..."
              maxLength={500}
            />
          </div>

          <div className="space-y-1.5">
            <Label>Style tags</Label>
            <StyleTagPicker
              selectedIds={selectedTagIds}
              onChange={setSelectedTagIds}
              tags={styleTags}
            />
          </div>

          <div className="flex items-center gap-2">
            <input
              id="edit-featured"
              type="checkbox"
              checked={isFeatured}
              onChange={(e) => setIsFeatured(e.target.checked)}
              className="h-4 w-4 rounded border-border"
            />
            <Label htmlFor="edit-featured" className="text-sm font-normal cursor-pointer">
              Feature on studio portfolio page
            </Label>
          </div>

          <DialogFooter>
            <Button variant="outline" type="button" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={saving}>
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Save
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

