interface HealedPhoto {
  id: string
  storage_path: string
  caption: string | null
  taken_at: string
}

const BOOKING_PHOTOS_URL = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''

function PromoteFromBookingDialog({ artistId, styleTags, open, onOpenChange, onAdded }: PromoteDialogProps) {
  const [photos, setPhotos] = useState<HealedPhoto[]>([])
  const [loading, setLoading] = useState(false)
  const [selected, setSelected] = useState<string[]>([])
  const [caption, setCaption] = useState('')
  const [selectedTagIds, setSelectedTagIds] = useState<string[]>([])
  const [promoting, setPromoting] = useState(false)

  useEffect(() => {
    if (!open) return
    setLoading(true)
    fetch(`/api/artists/${artistId}/healed-photos`)
      .then((r) => r.json())
      .then((j: unknown) => {
        if (j && typeof j === 'object' && 'data' in j && Array.isArray((j as { data: HealedPhoto[] }).data)) {
          setPhotos((j as { data: HealedPhoto[] }).data)
        }
      })
      .catch(() => null)
      .finally(() => setLoading(false))
  }, [open, artistId])

  async function handlePromote(e: React.FormEvent) {
    e.preventDefault()
    if (!selected.length) return
    setPromoting(true)
    try {
      await Promise.all(
        selected.map((photoId) =>
          fetch('/api/portfolio/promote', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              bookingPhotoId: photoId,
              artistId,
              caption: caption || null,
              styleTagIds: selectedTagIds,
            }),
          })
        )
      )
      toast.success(`${selected.length} photo${selected.length > 1 ? 's' : ''} added to portfolio`)
      onAdded()
      onOpenChange(false)
    } catch {
      toast.error('Failed to promote photos')
    } finally {
      setPromoting(false)
    }
  }

  function togglePhoto(id: string) {
    setSelected((prev) => prev.includes(id) ? prev.filter((s) => s !== id) : [...prev, id])
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>Promote healed photos to portfolio</DialogTitle>
        </DialogHeader>

        <form onSubmit={(e) => void handlePromote(e)} className="space-y-4 py-2">
          {loading ? (
            <div className="grid grid-cols-3 gap-2">
              {Array.from({ length: 6 }).map((_, i) => (
                <Skeleton key={i} className="aspect-square rounded-lg" />
              ))}
            </div>
          ) : photos.length === 0 ? (
            <p className="text-sm text-muted-foreground py-4 text-center">
              No healed photos found for this artist.
            </p>
          ) : (
            <div className="grid grid-cols-3 gap-2 max-h-64 overflow-y-auto">
              {photos.map((photo) => {
                const url = `${BOOKING_PHOTOS_URL}/storage/v1/object/public/booking-photos/${photo.storage_path}`
                const isSelected = selected.includes(photo.id)
                return (
                  <button
                    key={photo.id}
                    type="button"
                    onClick={() => togglePhoto(photo.id)}
                    className={cn(
                      'relative aspect-square rounded-lg overflow-hidden border-2 transition-all',
                      isSelected ? 'border-primary ring-1 ring-primary' : 'border-transparent hover:border-primary/40'
                    )}
                    aria-pressed={isSelected}
                    aria-label={photo.caption ?? 'Select photo'}
                  >
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    <img src={url} alt={photo.caption ?? 'Healed photo'} className="h-full w-full object-cover" loading="lazy" />
                    {isSelected && (
                      <div className="absolute inset-0 bg-primary/20 flex items-center justify-center">
                        <div className="h-5 w-5 rounded-full bg-primary text-primary-foreground flex items-center justify-center">
                          <span className="text-xs font-bold">✓</span>
                        </div>
                      </div>
                    )}
                  </button>
                )
              })}
            </div>
          )}

          {selected.length > 0 && (
            <>
              <div className="space-y-1.5">
                <Label htmlFor="promo-caption">Caption (applied to all selected)</Label>
                <Input
                  id="promo-caption"
                  value={caption}
                  onChange={(e) => setCaption(e.target.value)}
                  placeholder="Optional caption..."
                  maxLength={500}
                />
              </div>
              <div className="space-y-1.5">
                <Label>Style tags</Label>
                <StyleTagPicker selectedIds={selectedTagIds} onChange={setSelectedTagIds} tags={styleTags} />
              </div>
            </>
          )}

          <DialogFooter>
            <Button variant="outline" type="button" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={!selected.length || promoting}>
              {promoting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Promote {selected.length > 0 ? `(${selected.length})` : ''}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

// ── Main Manager ─────────────────────────────────────────────────────────────

interface ArtistPortfolioManagerProps {
  artistId: string
  canEdit: boolean
}

export function ArtistPortfolioManager({ artistId, canEdit }: ArtistPortfolioManagerProps) {
  const [items, setItems] = useState<ArtistPortfolioItem[]>([])
  const [styleTags, setStyleTags] = useState<StyleTag[]>([])
  const [loading, setLoading] = useState(true)
  const [addOpen, setAddOpen] = useState(false)
  const [promoteOpen, setPromoteOpen] = useState(false)
  const [editItem, setEditItem] = useState<ArtistPortfolioItem | null>(null)
  const [editOpen, setEditOpen] = useState(false)

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  )

  const fetchAll = useCallback(async () => {
    setLoading(true)
    try {
      const [portfolioRes, tagsRes] = await Promise.all([
        fetch(`/api/portfolio?artistId=${artistId}`),
        fetch('/api/style-tags'),
      ])
      const [portfolioJson, tagsJson] = await Promise.all([
        portfolioRes.json() as Promise<{ data: ArtistPortfolioItem[] }>,
        tagsRes.json() as Promise<{ data: StyleTag[] }>,
      ])
      setItems(portfolioJson.data ?? [])
      setStyleTags(tagsJson.data ?? [])
    } catch {
      toast.error('Failed to load portfolio')
    } finally {
      setLoading(false)
    }
  }, [artistId])

  useEffect(() => { void fetchAll() }, [fetchAll])

  async function handleToggleFeatured(id: string, current: boolean) {
    try {
      const res = await fetch(`/api/portfolio/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isFeatured: !current }),
      })
      if (!res.ok) throw new Error('Failed to update')
      setItems((prev) => prev.map((i) => i.id === id ? { ...i, is_featured: !current } : i))
      toast.success(current ? 'Removed from featured' : 'Added to featured')
    } catch {
      toast.error('Failed to update')
    }
  }

  async function handleDelete(id: string) {
    try {
      const res = await fetch(`/api/portfolio/${id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Delete failed')
      setItems((prev) => prev.filter((i) => i.id !== id))
      toast.success('Portfolio item deleted')
    } catch {
      toast.error('Failed to delete')
    }
  }

  function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event
    if (!over || active.id === over.id) return

    const oldIndex = items.findIndex((i) => i.id === active.id)
    const newIndex = items.findIndex((i) => i.id === over.id)
    const reordered = arrayMove(items, oldIndex, newIndex)
    setItems(reordered)

    fetch('/api/portfolio/reorder', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ orderedIds: reordered.map((i) => i.id) }),
    }).catch(() => toast.error('Failed to save order'))
  }

  const openEdit = (item: ArtistPortfolioItem) => {
    setEditItem(item)
    setEditOpen(true)
  }

  if (loading) {
    return (
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
        {Array.from({ length: 6 }).map((_, i) => (
          <Skeleton key={i} className="aspect-square rounded-xl" />
        ))}
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm font-medium">Portfolio</p>
          <p className="text-xs text-muted-foreground">
            {items.length} item{items.length !== 1 ? 's' : ''} · {items.filter((i) => i.is_featured).length} featured
          </p>
        </div>
        {canEdit && (
          <div className="flex items-center gap-2">
            <Button size="sm" variant="outline" onClick={() => setPromoteOpen(true)}>
              <Images className="h-3.5 w-3.5 mr-1.5" />
              From booking
            </Button>
            <Button size="sm" onClick={() => setAddOpen(true)}>
              <Upload className="h-3.5 w-3.5 mr-1.5" />
              Upload
            </Button>
          </div>
        )}
      </div>

      {items.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 text-center space-y-3">
          <div className="h-12 w-12 rounded-xl bg-muted flex items-center justify-center">
            <ImageIcon className="h-6 w-6 text-muted-foreground" />
          </div>
          <div className="space-y-1">
            <p className="text-sm font-medium">No portfolio items yet</p>
            <p className="text-xs text-muted-foreground max-w-xs">
              Upload work to showcase on the public artist booking page.
            </p>
          </div>
          {canEdit && (
            <div className="flex gap-2">
              <Button size="sm" variant="outline" onClick={() => setPromoteOpen(true)}>
                <Images className="h-3.5 w-3.5 mr-1.5" />
                From healed photos
              </Button>
              <Button size="sm" onClick={() => setAddOpen(true)}>
                <Upload className="h-3.5 w-3.5 mr-1.5" />
                Upload first photo
              </Button>
            </div>
          )}
        </div>
      ) : (
        <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
          <SortableContext items={items.map((i) => i.id)} strategy={rectSortingStrategy}>
            <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
              {items.map((item) => (
                <SortablePortfolioItem
                  key={item.id}
                  item={item}
                  styleTags={styleTags}
                  canEdit={canEdit}
                  onToggleFeatured={handleToggleFeatured}
                  onDelete={handleDelete}
                  onEdit={openEdit}
                />
              ))}
            </div>
          </SortableContext>
        </DndContext>
      )}

      {/* Featured count indicator */}
      {items.length > 0 && (
        <div className="flex items-center gap-1.5 text-xs text-muted-foreground pt-1">
          <Star className="h-3 w-3 text-warning" />
          <span>Featured items appear on the studio portfolio page</span>
        </div>
      )}

      <AddPortfolioItemDialog
        artistId={artistId}
        styleTags={styleTags}
        open={addOpen}
        onOpenChange={setAddOpen}
        onAdded={() => void fetchAll()}
      />

      <PromoteFromBookingDialog
        artistId={artistId}
        styleTags={styleTags}
        open={promoteOpen}
        onOpenChange={setPromoteOpen}
        onAdded={() => void fetchAll()}
      />

      <EditPortfolioItemDialog
        item={editItem}
        styleTags={styleTags}
        open={editOpen}
        onOpenChange={setEditOpen}
        onSaved={() => void fetchAll()}
      />
    </div>
  )
}

