import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { fetchStudioPortfolio } from '@/lib/portfolio/portfolio'
import { listStyleTags } from '@/lib/style-tags/style-tags'
import { createClient } from '@/lib/supabase/server'
import { StudioPortfolioGallery } from '@/components/portfolio/StudioPortfolioGallery'
import { Skeleton } from '@/components/ui/skeleton'

export const metadata: Metadata = {
  title: 'Flash & Portfolio — InkOS',
}

async function PortfolioContent() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()
  const { data: artists } = await supabase
    .from('artists')
    .select('id, display_name, slug, avatar_url')
    .eq('studio_id', auth.studioId)
    .eq('status', 'active')
    .order('sort_order', { ascending: true })

  const [items, styleTags] = await Promise.all([
    fetchStudioPortfolio(auth.studioId).catch(() => []),
    listStyleTags(auth.studioId).catch(() => []),
  ])

  return (
    <StudioPortfolioGallery
      items={items}
      styleTags={styleTags}
      artists={artists ?? []}
      canManage={['owner', 'admin'].includes(auth.role)}
    />
  )
}

function PortfolioSkeleton() {
  return (
    <div className="p-6 space-y-6">
      <Skeleton className="h-8 w-48" />
      <div className="flex gap-2">
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-8 w-20 rounded-full" />
        ))}
      </div>
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
        {Array.from({ length: 12 }).map((_, i) => (
          <Skeleton key={i} className="aspect-square rounded-xl" />
        ))}
      </div>
    </div>
  )
}

export default function PortfolioPage() {
  return (
    <Suspense fallback={<PortfolioSkeleton />}>
      <PortfolioContent />
    </Suspense>
  )
}

'use client'

import { useState, useMemo } from 'react'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'
import { ImageIcon, Settings, X } from 'lucide-react'
import { StyleTagChips } from '@/components/shared/StyleTagPicker'
import type { ArtistPortfolioItem, StyleTag } from '@/lib/supabase/types'

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''

function getPublicUrl(storagePath: string) {
  return `${SUPABASE_URL}/storage/v1/object/public/artist-portfolio/${storagePath}`
}

interface ArtistMini {
  id: string
  display_name: string
  slug: string | null
  avatar_url: string | null
}

interface PortfolioItemWithArtist extends ArtistPortfolioItem {
  artist: ArtistMini
}

interface StudioPortfolioGalleryProps {
  items: PortfolioItemWithArtist[]
  styleTags: StyleTag[]
  artists: ArtistMini[]
  canManage: boolean
}

// ── Lightbox ─────────────────────────────────────────────────────────────────

interface LightboxProps {
  item: PortfolioItemWithArtist
  styleTags: StyleTag[]
  onClose: () => void
  onPrev: (() => void) | null
  onNext: (() => void) | null
}

function Lightbox({ item, styleTags, onClose, onPrev, onNext }: LightboxProps) {
  return (
    <div
      className="fixed inset-0 z-50 bg-background/90 backdrop-blur-sm flex items-center justify-center"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-label="Portfolio photo viewer"
    >
      <button
        type="button"
        className="absolute top-4 right-4 h-8 w-8 rounded-full bg-foreground/10 flex items-center justify-center text-foreground hover:bg-foreground/20 transition-colors"
        onClick={onClose}
        aria-label="Close"
      >
        <X className="h-4 w-4" />
      </button>

      <div
        className="relative max-w-3xl w-full mx-4 space-y-3"
        onClick={(e) => e.stopPropagation()}
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={getPublicUrl(item.storage_path)}
          alt={item.caption ?? 'Portfolio photo'}
          className="w-full max-h-[75vh] object-contain rounded-xl"
        />

        <div className="space-y-1">
          <div className="flex items-center justify-between">
            <Link
              href={`/artists/${item.artist_id}?tab=portfolio`}
              className="text-sm font-medium hover:underline"
            >
              {item.artist.display_name}
            </Link>
            {item.is_featured && (
              <Badge variant="secondary" className="text-xs">Featured</Badge>
            )}
          </div>
          {item.caption && (
            <p className="text-sm text-muted-foreground">{item.caption}</p>
          )}
          {item.style_tag_ids.length > 0 && (
            <StyleTagChips tagIds={item.style_tag_ids} tags={styleTags} />
          )}
        </div>

        {/* Navigation */}
        <div className="flex justify-between pt-1">
          {onPrev ? (
            <Button size="sm" variant="outline" onClick={onPrev}>
              ← Previous
            </Button>
          ) : <div />}
          {onNext ? (
            <Button size="sm" variant="outline" onClick={onNext}>
              Next →
            </Button>
          ) : <div />}
        </div>
      </div>
    </div>
  )
}

// ── Main Gallery ─────────────────────────────────────────────────────────────

export function StudioPortfolioGallery({ items, styleTags, artists, canManage }: StudioPortfolioGalleryProps) {
  const [selectedArtistId, setSelectedArtistId] = useState<string | null>(null)
  const [selectedTagId, setSelectedTagId] = useState<string | null>(null)
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null)

  const filteredItems = useMemo(() => {
    return items.filter((item) => {
      if (selectedArtistId && item.artist_id !== selectedArtistId) return false
      if (selectedTagId && !item.style_tag_ids.includes(selectedTagId)) return false
      return true
    })
  }, [items, selectedArtistId, selectedTagId])

  const activeStyleTags = useMemo(() => {
    const usedIds = new Set(items.flatMap((i) => i.style_tag_ids))
    return styleTags.filter((t) => usedIds.has(t.id))
  }, [items, styleTags])

  const activeArtists = useMemo(() => {
    const usedIds = new Set(items.map((i) => i.artist_id))
    return artists.filter((a) => usedIds.has(a.id))
  }, [items, artists])

  if (items.length === 0) {
    return (
      <div className="p-6">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-lg font-semibold">Flash &amp; Portfolio</h1>
            <p className="text-sm text-muted-foreground mt-0.5">Studio portfolio gallery</p>
          </div>
          {canManage && (
            <Button size="sm" variant="outline" render={<Link href="/artists" />}>
              <Settings className="h-3.5 w-3.5 mr-1.5" />
              Manage artists
            </Button>
          )}
        </div>
        <div className="flex flex-col items-center justify-center py-24 text-center space-y-3">
          <div className="h-14 w-14 rounded-2xl bg-muted flex items-center justify-center">
            <ImageIcon className="h-7 w-7 text-muted-foreground" />
          </div>
          <p className="text-base font-semibold">No portfolio items yet</p>
          <p className="text-sm text-muted-foreground max-w-sm">
            Artists can upload work from their profile page. Featured items will appear here.
          </p>
          {canManage && (
            <Button size="sm" variant="outline" render={<Link href="/artists" />}>
              Go to artists
            </Button>
          )}
        </div>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-lg font-semibold">Flash &amp; Portfolio</h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            {filteredItems.length} of {items.length} item{items.length !== 1 ? 's' : ''}
          </p>
        </div>
        {canManage && (
          <Button size="sm" variant="outline" render={<Link href="/artists" />}>
            <Settings className="h-3.5 w-3.5 mr-1.5" />
            Manage
          </Button>
        )}
      </div>

      {/* Filters */}
      <div className="space-y-2">
        {/* Artist filter */}
        {activeArtists.length > 1 && (
          <div className="flex flex-wrap gap-1.5">
            <button
              type="button"
              onClick={() => setSelectedArtistId(null)}
              className={cn(
                'rounded-full border px-3 py-1 text-xs font-medium transition-colors',
                !selectedArtistId
                  ? 'border-primary bg-primary/10 text-primary'
                  : 'border-border/60 bg-muted/50 text-muted-foreground hover:border-primary/40'
              )}
            >
              All artists
            </button>
            {activeArtists.map((artist) => (
              <button
                key={artist.id}
                type="button"
                onClick={() => setSelectedArtistId(selectedArtistId === artist.id ? null : artist.id)}
                className={cn(
                  'rounded-full border px-3 py-1 text-xs font-medium transition-colors',
                  selectedArtistId === artist.id
                    ? 'border-primary bg-primary/10 text-primary'
                    : 'border-border/60 bg-muted/50 text-muted-foreground hover:border-primary/40'
                )}
              >
                {artist.display_name}
              </button>
            ))}
          </div>
        )}

        {/* Style tag filter */}
        {activeStyleTags.length > 0 && (
          <div className="flex flex-wrap gap-1.5">
            {activeStyleTags.map((tag) => (
              <button
                key={tag.id}
                type="button"
                onClick={() => setSelectedTagId(selectedTagId === tag.id ? null : tag.id)}
                className={cn(
                  'inline-flex items-center gap-1 rounded-full border px-2.5 py-0.5 text-xs font-medium transition-colors',
                  selectedTagId === tag.id
                    ? 'border-primary bg-primary/10 text-primary'
                    : 'border-border/60 bg-muted/50 text-muted-foreground hover:border-primary/40'
                )}
              >
                {tag.color && (
                  <span
                    className="h-1.5 w-1.5 rounded-full shrink-0"
                    style={{ backgroundColor: tag.color }}
                  />
                )}
                {tag.name}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Gallery grid */}
      {filteredItems.length === 0 ? (
        <div className="py-12 text-center text-sm text-muted-foreground">
          No items match the selected filters.
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
          {filteredItems.map((item, index) => (
            <button
              key={item.id}
              type="button"
              onClick={() => setLightboxIndex(index)}
              className="group relative rounded-xl overflow-hidden border border-border/50 bg-muted aspect-square focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              aria-label={item.caption ?? `Portfolio item by ${item.artist.display_name}`}
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={getPublicUrl(item.storage_path)}
                alt={item.caption ?? 'Portfolio photo'}
                className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-105"
                loading="lazy"
              />
              {/* Hover overlay */}
              <div className="absolute inset-0 bg-background/70 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center p-2 text-center gap-1">
                <p className="text-xs font-semibold">{item.artist.display_name}</p>
                {item.caption && (
                  <p className="text-[10px] text-muted-foreground line-clamp-2">{item.caption}</p>
                )}
              </div>
            </button>
          ))}
        </div>
      )}

      {/* Lightbox */}
      {lightboxIndex !== null && filteredItems[lightboxIndex] && (
        <Lightbox
          item={filteredItems[lightboxIndex]}
          styleTags={styleTags}
          onClose={() => setLightboxIndex(null)}
          onPrev={lightboxIndex > 0 ? () => setLightboxIndex(lightboxIndex - 1) : null}
          onNext={lightboxIndex < filteredItems.length - 1 ? () => setLightboxIndex(lightboxIndex + 1) : null}
        />
      )}
    </div>
  )
}

