import { NextResponse } from 'next/server'
import { createPublicClient } from '@/lib/supabase/public'
import { publicBookingReadRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export async function GET(
  req: Request,
  { params }: { params: Promise<{ studioSlug: string }> }
) {
  const { studioSlug } = await params
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await publicBookingReadRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const supabase = createPublicClient()

  try {
    // Resolve studio
    const { data: studio } = await supabase
      .from('studios')
      .select('id')
      .eq('slug', studioSlug)
      .maybeSingle()

    if (!studio) return NextResponse.json({ data: [] })

    const today = new Date().toISOString().split('T')[0]

    // Fetch published upcoming events
    const { data: events, error } = await supabase
      .from('flash_events')
      .select(`
        id, title, slug, event_date, cover_image_url,
        slot_price_cents, deposit_cents, currency,
        artist:artists(display_name)
      `)
      .eq('studio_id', studio.id)
      .eq('status', 'published')
      .eq('public', true)
      .gte('event_date', today)
      .order('event_date', { ascending: true })
      .limit(6)

    if (error) {
      logger.error({ error, studioSlug }, 'GET upcoming flash events failed')
      return NextResponse.json({ data: [] })
    }

    if (!events || events.length === 0) return NextResponse.json({ data: [] })

    // Fetch slot summaries in bulk
    const eventIds = events.map((e) => e.id)
    const { data: slots } = await supabase
      .from('flash_event_slots')
      .select('flash_event_id, status')
      .in('flash_event_id', eventIds)

    const slotMap = new Map<string, { total: number; available: number }>()
    for (const slot of slots ?? []) {
      const entry = slotMap.get(slot.flash_event_id) ?? { total: 0, available: 0 }
      entry.total += 1
      if (slot.status === 'open') entry.available += 1
      slotMap.set(slot.flash_event_id, entry)
    }

    const enriched = events.map((e) => {
      const sm = slotMap.get(e.id) ?? { total: 0, available: 0 }
      return {
        ...e,
        artist: Array.isArray(e.artist) ? (e.artist[0] ?? null) : (e.artist ?? null),
        slots_available: sm.available,
        slots_total: sm.total,
      }
    })

    return NextResponse.json({ data: enriched })
  } catch (err) {
    logger.error({ err, studioSlug }, 'GET /api/public/flash/[studioSlug]/upcoming unexpected error')
    return NextResponse.json({ data: [] })
  }
}

import { NextResponse } from 'next/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export async function GET(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin', 'artist'].includes(auth.role)) {
    return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 })
  }

  const supabase = await createClient()

  try {
    // Verify artist belongs to studio
    const { data: artist } = await supabase
      .from('artists')
      .select('id')
      .eq('id', id)
      .eq('studio_id', auth.studioId)
      .maybeSingle()

    if (!artist) return NextResponse.json({ error: 'Artist not found' }, { status: 404 })

    // Get healed booking photos for this artist
    const { data, error } = await supabase
      .from('booking_photos')
      .select(`
        id, storage_path, caption, taken_at,
        booking:bookings!inner(artist_id)
      `)
      .eq('studio_id', auth.studioId)
      .eq('kind', 'healed')
      .eq('booking.artist_id', id)
      .order('taken_at', { ascending: false })
      .limit(50)

    if (error) {
      logger.error({ error, id }, 'GET /api/artists/[id]/healed-photos failed')
      return NextResponse.json({ error: 'Failed to load photos' }, { status: 500 })
    }

    // Return just the photo data (without the join)
    const photos = (data ?? []).map((p) => ({
      id: p.id,
      storage_path: p.storage_path,
      caption: p.caption,
      taken_at: p.taken_at,
    }))

    return NextResponse.json({ data: photos })
  } catch (err) {
    logger.error({ err, id }, 'GET /api/artists/[id]/healed-photos unexpected error')
    return NextResponse.json({ error: 'Internal error' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { addDesign, reorderDesigns } from '@/lib/flash-events/mutations'
import { flashDesignCreateSchema } from '@/lib/flash-events/schemas'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

// POST — add a design OR reorder (action discriminated by ?action=reorder)
export async function POST(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin', 'artist', 'receptionist'].includes(auth.role)) {
    return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 })
  }

  const url = new URL(req.url)
  const action = url.searchParams.get('action')

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  if (action === 'reorder') {
    const parsed = z.object({ orderedIds: z.array(z.string().uuid()).min(1) }).safeParse(body)
    if (!parsed.success) return NextResponse.json({ error: 'orderedIds required' }, { status: 400 })
    await reorderDesigns(auth.studioId, id, parsed.data.orderedIds)
    return NextResponse.json({ success: true })
  }

  const parsed = flashDesignCreateSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.errors[0]?.message ?? 'Validation failed' }, { status: 400 })
  }

  try {
    const design = await addDesign(auth.studioId, id, parsed.data)
    return NextResponse.json({ data: design }, { status: 201 })
  } catch (err) {
    logger.error({ err, id }, 'POST /api/flash-events/[id]/designs failed')
    const message = err instanceof Error ? err.message : 'Failed to add design'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { updateDesign, removeDesign } from '@/lib/flash-events/mutations'
import { flashDesignUpdateSchema } from '@/lib/flash-events/schemas'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export async function PATCH(
  req: Request,
  { params }: { params: Promise<{ id: string; designId: string }> }
) {
  const { id, designId } = await params
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin', 'artist', 'receptionist'].includes(auth.role)) {
    return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = flashDesignUpdateSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.errors[0]?.message ?? 'Validation failed' }, { status: 400 })
  }

  try {
    const design = await updateDesign(auth.studioId, id, designId, parsed.data)
    return NextResponse.json({ data: design })
  } catch (err) {
    logger.error({ err, id, designId }, 'PATCH /api/flash-events/[id]/designs/[designId] failed')
    const message = err instanceof Error ? err.message : 'Failed to update design'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

export async function DELETE(
  req: Request,
  { params }: { params: Promise<{ id: string; designId: string }> }
) {
  const { id, designId } = await params
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin', 'artist', 'receptionist'].includes(auth.role)) {
    return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 })
  }

  try {
    await removeDesign(auth.studioId, id, designId)
    return NextResponse.json({ success: true })
  } catch (err) {
    logger.error({ err, id, designId }, 'DELETE /api/flash-events/[id]/designs/[designId] failed')
    return NextResponse.json({ error: 'Failed to remove design' }, { status: 500 })
  }
}

