import type { Metadata } from 'next'
import { redirect, notFound } from 'next/navigation'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { getFlashEvent, getFlashEventSlots } from '@/lib/flash-events/queries'
import { listStyleTags } from '@/lib/style-tags/style-tags'
import { FlashEventDetailShell } from '@/components/flash-events/FlashEventDetailShell'

interface Props {
  params: Promise<{ id: string }>
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export async function generateMetadata(): Promise<Metadata> {
  return { title: 'Flash Event — InkOS' }
}

export default async function FlashEventDetailPage({ params, searchParams }: Props) {
  const { id } = await params
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const resolvedSearch = await searchParams
  const tab = typeof resolvedSearch.tab === 'string' ? resolvedSearch.tab : 'overview'

  const [event, slots, styleTags] = await Promise.all([
    getFlashEvent(auth.studioId, id),
    getFlashEventSlots(auth.studioId, id).catch(() => []),
    listStyleTags(auth.studioId).catch(() => []),
  ])

  if (!event) notFound()

  return (
    <FlashEventDetailShell
      event={event}
      slots={slots}
      role={auth.role}
      initialTab={tab}
      studioId={auth.studioId}
      styleTags={styleTags}
    />
  )
}

