'use client'

import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Card, CardContent } from '@/components/ui/card'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog'
import { Plus, Trash2, ImageIcon, Tag } from 'lucide-react'
import { cn, formatCurrency } from '@/lib/utils'
import type { FlashEventDetail } from '@/lib/flash-events/queries'
import type { StyleTag } from '@/lib/supabase/types'
import { AddDesignDialog } from './AddDesignDialog'

interface Props {
  event: FlashEventDetail
  canEdit: boolean
  styleTags: StyleTag[]
  onRemove: (designId: string) => void
  onReorder: (orderedIds: string[]) => void
  onToggleSoldOut: (designId: string, soldOut: boolean) => void
}

export function FlashEventDesignsTab({ event, canEdit, styleTags, onRemove, onToggleSoldOut }: Props) {
  const [addOpen, setAddOpen] = useState(false)
  const designs = event.designs

  // Build a map for quick tag lookup
  const tagMap = new Map<string, StyleTag>(styleTags.map((t) => [t.id, t]))

  return (
    <div className="space-y-4 max-w-2xl">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm font-medium">Flash designs</p>
          <p className="text-xs text-muted-foreground">
            {designs.length} design{designs.length !== 1 ? 's' : ''} on this event
          </p>
        </div>
        {canEdit && (
          <Button size="sm" onClick={() => setAddOpen(true)}>
            <Plus className="h-3.5 w-3.5 mr-1.5" />
            Add design
          </Button>
        )}
      </div>

      {designs.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 text-center space-y-3">
          <div className="h-12 w-12 rounded-xl bg-muted flex items-center justify-center">
            <ImageIcon className="h-6 w-6 text-muted-foreground" />
          </div>
          <div className="space-y-1">
            <p className="text-sm font-medium">No designs yet</p>
            <p className="text-xs text-muted-foreground max-w-xs">
              Add flash designs clients can browse and select when booking.
            </p>
          </div>
          {canEdit && (
            <Button size="sm" variant="outline" onClick={() => setAddOpen(true)}>
              <Plus className="h-3.5 w-3.5 mr-1.5" />
              Add first design
            </Button>
          )}
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
          {designs.map((design) => {
            const designTags = (design.style_tag_ids ?? [])
              .map((tid) => tagMap.get(tid))
              .filter((t): t is StyleTag => t !== undefined)

            return (
              <Card
                key={design.id}
                className={cn(
                  'overflow-hidden border-border/60',
                  design.sold_out && 'opacity-60'
                )}
              >
                {/* Design image */}
                <div className="relative aspect-square bg-muted overflow-hidden">
                  {design.image_url ? (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img
                      src={design.image_url}
                      alt={design.title}
                      className="h-full w-full object-cover"
                    />
                  ) : (
                    <div className="h-full w-full flex items-center justify-center">
                      <ImageIcon className="h-8 w-8 text-muted-foreground/30" />
                    </div>
                  )}
                  {design.sold_out && (
                    <div className="absolute inset-0 bg-background/60 flex items-center justify-center">
                      <Badge variant="destructive" className="text-xs">Sold out</Badge>
                    </div>
                  )}
                </div>

                <CardContent className="p-2.5 space-y-2">
                  <p className="text-xs font-semibold line-clamp-1">{design.title}</p>

                  <div className="space-y-0.5">
                    {design.size_description && (
                      <p className="text-[10px] text-muted-foreground">{design.size_description}</p>
                    )}
                    {design.price_cents != null && (
                      <div className="flex items-center gap-1">
                        <Tag className="h-2.5 w-2.5 text-muted-foreground" />
                        <p className="text-[10px] font-medium">{formatCurrency(design.price_cents)}</p>
                      </div>
                    )}
                  </div>

                  {/* Style tag chips */}
                  {designTags.length > 0 && (
                    <div className="flex flex-wrap gap-1">
                      {designTags.slice(0, 3).map((tag) => (
                        <span
                          key={tag.id}
                          className="inline-flex items-center rounded-full px-1.5 py-0.5 text-[9px] font-medium leading-none"
                          style={{
                            backgroundColor: tag.color ? `${tag.color}22` : undefined,
                            color: tag.color ?? undefined,
                            border: `1px solid ${tag.color ?? 'hsl(var(--border))'}44`,
                          }}
                        >
                          {tag.name}
                        </span>
                      ))}
                      {designTags.length > 3 && (
                        <span className="text-[9px] text-muted-foreground leading-none self-center">
                          +{designTags.length - 3}
                        </span>
                      )}
                    </div>
                  )}

                  {canEdit && (
                    <div className="flex items-center gap-1">
                      <Button
                        variant="outline"
                        size="sm"
                        className="flex-1 h-6 text-[10px]"
                        onClick={() => onToggleSoldOut(design.id, !design.sold_out)}
                      >
                        {design.sold_out ? 'Mark available' : 'Sold out'}
                      </Button>
                      <AlertDialog>
                        <AlertDialogTrigger>
                          <Button variant="ghost" size="icon" className="h-6 w-6 text-destructive hover:text-destructive">
                            <Trash2 className="h-3 w-3" />
                          </Button>
                        </AlertDialogTrigger>
                        <AlertDialogContent>
                          <AlertDialogHeader>
                            <AlertDialogTitle>Remove design?</AlertDialogTitle>
                            <AlertDialogDescription>
                              This will remove &ldquo;{design.title}&rdquo; from the event. This cannot be undone.
                            </AlertDialogDescription>
                          </AlertDialogHeader>
                          <AlertDialogFooter>
                            <AlertDialogCancel>Cancel</AlertDialogCancel>
                            <AlertDialogAction
                              onClick={() => onRemove(design.id)}
                              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                            >
                              Remove
                            </AlertDialogAction>
                          </AlertDialogFooter>
                        </AlertDialogContent>
                      </AlertDialog>
                    </div>
                  )}
                </CardContent>
              </Card>
            )
          })}
        </div>
      )}

      {addOpen && (
        <AddDesignDialog
          eventId={event.id}
          open={addOpen}
          onOpenChange={setAddOpen}
        />
      )}
    </div>
  )
}

